INSERT INTO `attestations` (`id`,`form_id`,`source_id`,`date_label`,`year`,`witness`,`locator`,`excerpt`,`confidence`,`witness_type`,`repository`,`shelfmark`,`facsimile_url`,`directly_inspected`,`editorial_note`) VALUES
(90,102,100,'1704',1704,'John Harris’s Lexicon technicum prints ALGEBRA as a headword and identifies it as an analytic art concerned with equations.','Image [53], right column, entry ALGEBRA; e-rara content image 2867117','ALGEBRA; the wonderful Analytick Art, or the Art of Equation.','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867117','https://www.e-rara.ch/zut/content/zoom/2867117?query=ALGEBRA',1,'The e-rara page image was directly inspected. It verifies the ALGEBRA headword and opening definition in Harris’s 1704 English dictionary; it is not claimed as the earliest English occurrence or as evidence for the deeper Arabic lineage.'),
(91,198,100,'1704',1704,'John Harris’s Lexicon technicum prints DECIMAL in the head phrase DECIMAL Fraction and begins its mathematical definition.','Image [251], left column, entry DECIMAL Fraction; e-rara content image 2867315','DECIMAL Fraction, is that which hath for its Denominator 1. with a Cypher or Cyphers annexed;','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867315','https://www.e-rara.ch/zut/content/zoom/2867315?query=DECIMAL',1,'The e-rara page image was directly inspected. It verifies DECIMAL in a 1704 English mathematical head phrase; it is not claimed as the earliest English occurrence and does not by itself prove the word’s French or Latin ancestry.'),
(92,107,100,'1704',1704,'The CHIMES entry in John Harris’s Lexicon technicum uses calculate in instructions about clock-chime numbers.','Image [161], right column, CHIMES entry; e-rara content image 2867225','CHIMES of any Clock; How to calculate Numbers for them, and to fit and divide the Chime Barrel: See in Watch-work.','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867225','https://www.e-rara.ch/zut/content/zoom/2867225?query=CALCULATE',1,'The e-rara page image was directly inspected. It verifies a contextual English use of calculate in 1704 inside the CHIMES entry; it is not a CALCULATE headword and is not claimed as the earliest occurrence.'),
(93,118,100,'1704',1704,'John Harris’s Lexicon technicum prints MUSCLE as a headword and defines its role in voluntary animal motion.','Image [563], left column, entry MUSCLE; e-rara content image 2867627','MUSCLE, the chief Instrument of Voluntary Motion in an Animal Body.','established','printed_book','ETH-Bibliothek Zürich','Rar 98 Ex.A GF, content image 2867627','https://www.e-rara.ch/zut/content/zoom/2867627?query=MUSCLE',1,'The e-rara page image was directly inspected. It verifies the MUSCLE headword and opening definition in Harris’s 1704 English dictionary; it is not claimed as the earliest English occurrence or as proof of the historical mouse metaphor.');
